export async function synthesizeLowLatencySpeech(text: string, outputPath: string) {
  const speech = await openai.audio.speech.create({
    model: "tts-1",
    voice: "nova",
    input: text,
    response_format: "mp3"
  });

  await fs.promises.writeFile(outputPath, Buffer.from(await speech.arrayBuffer()));
}

